ValidationRule.errorConditionFormula:
AND(
    /* Global VR disable switch */
    $Setup.Salesforce_Library_Settings__c.Disable_VRs__c = false,
    /* Only fire when owner changes */
    ISCHANGED(OwnerId),
    /* Only fire when assigning to Digital Fraud Queue */
    Owner:Queue.QueueName = 'Digital Fraud Queue',
    /* Block if NOT in allowed combinations */
    NOT(
        OR(
            /* Always allowed record types */
            RecordType.DeveloperName = 'Scam',
            RecordType.DeveloperName = 'Recipient_Mule',
            RecordType.DeveloperName = 'Fraud',
            RecordType.DeveloperName = 'False_Customer_Profile',
            RecordType.DeveloperName = 'KYC_QA',
            RecordType.DeveloperName = 'Identity',
            RecordType.DeveloperName = 'PIN_Recovery',
            RecordType.DeveloperName = 'Selfie_Recovery',
            /* NPP/Direct Entry/BPAY: Requires Unauthorised Transaction */
            AND(
                OR(
                    RecordType.DeveloperName = 'NPP_Dispute',
                    RecordType.DeveloperName = 'Direct_Entry_Dispute',
                    RecordType.DeveloperName = 'BPAY_Dispute'
                ),
                ISPICKVAL(Dispute_Reason__c, 'Unauthorised Transaction')
            ),
            /* IMT: Requires Suspected fraud */
            AND(
                RecordType.DeveloperName = 'IMT_Dispute',
                ISPICKVAL(Dispute_Reason__c, 'Suspected fraud')
            )
        )
    )
)
